import CoreML
import Foundation
import MusicCore
import Testing
@testable import AnalysisEngine

/// End-to-end checks on the bundled demo song, compared with the reference basic-pitch output in
/// `Tests/Fixtures` (generated by `tools/fixtures/make_golden.py`). The simulator reads the host
/// file system, so fixtures are loaded by path.
private enum Paths {
    static let repo = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
    static let demo = repo.appendingPathComponent("Sources/RiffnexApp/Resources/Demo/riffnex-demo.m4a")
    static let activations = repo.appendingPathComponent("Tests/Fixtures/demo-activations.bin")
    static let truth = repo.appendingPathComponent("tools/fixtures/riffnex-demo.truth.json")
}

private struct Truth: Decodable {
    struct Note: Decodable { let onset: Double; let midi: Int }
    let notes: [Note]
}

private func referenceNotes() throws -> [Float] {
    let data = try Data(contentsOf: Paths.activations)
    let frames = data.withUnsafeBytes { Int(UInt32(littleEndian: $0.loadUnaligned(fromByteOffset: 4, as: UInt32.self))) }
    let bins = data.withUnsafeBytes { Int(UInt32(littleEndian: $0.loadUnaligned(fromByteOffset: 8, as: UInt32.self))) }
    return data.withUnsafeBytes { raw in
        (0..<(frames * bins)).map { Float(Double(UInt16(littleEndian: raw.loadUnaligned(fromByteOffset: 12 + 2 * $0, as: UInt16.self))) / 65535) }
    }
}

private final class UpdateLog: @unchecked Sendable {
    private let lock = NSLock()
    private var items: [AnalysisCoordinator.Update] = []
    func append(_ u: AnalysisCoordinator.Update) { lock.lock(); items.append(u); lock.unlock() }
    var all: [AnalysisCoordinator.Update] { lock.lock(); defer { lock.unlock() }; return items }
}

@Suite("AnalysisCoordinator on the demo", .serialized)
struct AnalysisCoordinatorTests {
    @Test(.timeLimit(.minutes(5)))
    func coreMLMatchesReferenceAndFindsTheRiff() async throws {
        let model = BasicPitchModel()
        let decoded = try AudioDecoder.decodeMono(url: Paths.demo, sampleRate: BasicPitchModel.Constants.sampleRate)
        try await model.load(computeUnits: .cpuOnly)
        let activations = try await AnalysisCoordinator.runBasicPitch(samples: decoded.samples, model: model,
                                                                      computeUnits: .cpuOnly) { _ in }
        let reference = try referenceNotes()
        let frames = min(activations.notes.values.count, reference.count) / 88
        #expect(abs(activations.notes.frames - reference.count / 88) <= 2, "frame count \(activations.notes.frames) vs \(reference.count / 88)")

        var absError = 0.0
        var maxError: Float = 0
        for i in 0..<(frames * 88) {
            let e = abs(activations.notes.values[i] - reference[i])
            absError += Double(e)
            maxError = max(maxError, e)
        }
        let mae = absError / Double(frames * 88)
        print("[coreml vs onnx] note activations MAE \(mae), max \(maxError) over \(frames) frames")
        // Different decoders/resamplers (AVAudioConverter vs ffmpeg) and runtimes: small, not zero.
        #expect(mae < 0.01)

        let input = AnalysisAssembler.Input(duration: decoded.duration, notes: activations.notes, onsets: activations.onsets,
                                            musicUnderstanding: nil, musicUnderstandingVersion: "none",
                                            basicPitchVersion: BasicPitchModel.Constants.modelVersion)
        let analysis = AnalysisAssembler.assemble(input)
        let truth = try JSONDecoder().decode(Truth.self, from: Data(contentsOf: Paths.truth))
        let score = TranscriptionMetrics.score(reference: truth.notes.map { .init(onset: $0.onset, pitch: $0.midi) },
                                               estimated: analysis.notes.map { .init(onset: $0.onset, pitch: $0.pitch.value) })
        print("[coreml pipeline] notes \(score)")
        #expect(score.f1 >= 0.65)
        #expect(analysis.chords.contains { $0.chord?.symbol() == "G5" })
    }

    @Test(.timeLimit(.minutes(5)))
    func fullAnalysisReportsRealProgress() async throws {
        let log = UpdateLog()
        let coordinator = AnalysisCoordinator()
        let analysis = try await coordinator.analyze(fileURL: Paths.demo,
                                                     options: .init(computeUnits: .cpuOnly, runMusicUnderstanding: true)) {
            log.append($0)
        }
        let updates = log.all
        let noteFractions = updates.filter { $0.stage == .notes }.compactMap(\.fraction)
        #expect(noteFractions.first == 0)
        #expect(noteFractions.last == 1)
        #expect(zip(noteFractions, noteFractions.dropFirst()).allSatisfy { $0 <= $1 })
        #expect(updates.contains { $0.stage == .decoding })
        #expect(updates.last?.stage == .assembling)
        #expect(analysis.notes.count > 30)
        #expect(analysis.timings.contains { $0.stage == "notes" })
        // Music Understanding may be unavailable in the simulator; either it worked or the failure is recorded.
        print("[coordinator] MU rhythm: \(analysis.rhythm?.beatsPerMinute.map { "\($0) BPM" } ?? "none"), key \(analysis.mainKey?.name() ?? "none"), errors \(analysis.stageErrors), timings \(analysis.timings.map { "\($0.stage)=\(String(format: "%.2f", $0.seconds))" })")
        #expect(analysis.rhythm != nil || analysis.stageErrors["musicUnderstanding"] != nil)
    }

    @Test(.timeLimit(.minutes(2)))
    func cancellationStopsCleanly() async throws {
        let coordinator = AnalysisCoordinator()
        let task = Task {
            try await coordinator.analyze(fileURL: Paths.demo, options: .init(computeUnits: .cpuOnly, runMusicUnderstanding: false)) { _ in }
        }
        task.cancel()
        await #expect(throws: CancellationError.self) { _ = try await task.value }
    }

    @Test func windowFilling() {
        var window = [Float](repeating: 9, count: 8)
        let samples: [Float] = [1, 2, 3, 4, 5]
        AnalysisCoordinator.fillWindow(&window, from: samples, start: -3)
        #expect(window == [0, 0, 0, 1, 2, 3, 4, 5])
        AnalysisCoordinator.fillWindow(&window, from: samples, start: 2)
        #expect(window == [3, 4, 5, 0, 0, 0, 0, 0])
        AnalysisCoordinator.fillWindow(&window, from: samples, start: 10)
        #expect(window == [0, 0, 0, 0, 0, 0, 0, 0])
    }
}
